#> fig-disp-compare
grid <- data.frame(
  concentration = exp(seq(log(min(ametryn$concentration)),
                          log(max(ametryn$concentration)), length.out = 100)))
# The formula term is log(concentration), which brms holds as its own column, so
# newdata has to supply it rather than leaving it to be derived.
grid[["log(concentration)"]] <- log(grid$concentration)

pp_band <- function(fit, label) {
  p <- predict(pull_brmsfit(fit), newdata = grid)
  data.frame(concentration = grid$concentration, fit = label,
             Estimate = p[, "Estimate"], Q2.5 = p[, "Q2.5"], Q97.5 = p[, "Q97.5"])
}

bands <- rbind(pp_band(best_fit, "constant dispersion"),
               pp_band(m7_am_disp, "disp(~ log(concentration))"))

ggplot(bands, aes(x = concentration)) +
  geom_ribbon(aes(ymin = Q2.5, ymax = Q97.5), fill = "grey80") +
  geom_line(aes(y = Estimate)) +
  geom_point(data = ametryn, aes(y = fvfm), size = 1.2, alpha = 0.6) +
  facet_wrap(~ fit) +
  scale_x_continuous(transform = "log", breaks = conc_breaks) +
  labs(x = expression(paste("Concentration (", mu, "g ", L^-1, ")")),
       y = "Maximum effective quantum yield") +
  theme_classic()

